<?php
session_start();
if (empty($_SESSION['admin'])) { header('Location: login.php'); exit; }
require __DIR__.'/config/db.php';
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$msg=''; $err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){ $err='انتهت صلاحية الطلب. أعد تحميل الصفحة.'; }
  else {
    $action=$_POST['action']??'';
    try{
      if($action==='create'){
        $name=trim($_POST['key_name']??''); if($name==='')$name='API '.date('Y-m-d H:i');
        $key=bin2hex(random_bytes(32));
        $st=$pdo->prepare('INSERT INTO api_keys(key_name,api_key,is_active) VALUES(?,?,1)');$st->execute([mb_substr($name,0,120),$key]);
        $msg='تم إنشاء API Key جديد بنجاح.';
      } elseif($action==='toggle'){
        $id=(int)($_POST['id']??0); $st=$pdo->prepare('UPDATE api_keys SET is_active=IF(is_active=1,0,1) WHERE id=?');$st->execute([$id]);$msg='تم تحديث حالة المفتاح.';
      } elseif($action==='delete'){
        $id=(int)($_POST['id']??0); $active=(int)$pdo->query('SELECT COUNT(*) FROM api_keys WHERE is_active=1')->fetchColumn();
        $st=$pdo->prepare('SELECT is_active FROM api_keys WHERE id=?');$st->execute([$id]);$row=$st->fetch();
        if($row && (int)$row['is_active']===1 && $active<=1) throw new Exception('لا يمكن حذف آخر مفتاح API فعال. أنشئ مفتاحاً جديداً أولاً.');
        $st=$pdo->prepare('DELETE FROM api_keys WHERE id=?');$st->execute([$id]);$msg='تم حذف المفتاح.';
      }
    }catch(Throwable $e){$err=$e->getMessage();}
  }
}
$_SESSION['csrf']=bin2hex(random_bytes(24));
$keys=$pdo->query('SELECT * FROM api_keys ORDER BY id DESC')->fetchAll();
$scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$base=rtrim(dirname($_SERVER['SCRIPT_NAME']),'/\\');$push=$scheme.'://'.($_SERVER['HTTP_HOST']??'').$base.'/api/push.php';
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#ffffff"><title>إدارة API | NotifyBridge V5.0</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="api-page"><div class="panel-head"><div><span class="eyebrow">SECURITY CENTER · V5.0</span><h1>إدارة مفاتيح API</h1><p style="color:#7693a5">أنشئ مفاتيح مستقلة لكل هاتف، اعرضها أو عطّلها وتابع آخر استخدام.</p></div><a class="btn soft" style="text-decoration:none" href="index.php">← العودة للوحة التحكم</a></div><?php if($msg):?><div class="api-card" style="background:#ecfbf5;color:#168e60"><?=h($msg)?></div><?php endif?><?php if($err):?><div class="api-card" style="background:#fff0f2;color:#c74359"><?=h($err)?></div><?php endif?><section class="api-card"><span class="eyebrow">ENDPOINT</span><h2>رابط استقبال الإشعارات</h2><div class="endpoint" id="endpoint"><?=h($push)?></div><button id="copyEndpoint" class="btn soft" type="button" style="margin-top:10px">نسخ الرابط</button></section><section class="api-card"><span class="eyebrow">NEW KEY</span><h2>إنشاء API Key جديد</h2><form method="post" class="create"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="action" value="create"><input name="key_name" maxlength="120" placeholder="مثال: هاتف أحمد" required><button class="btn primary" type="submit">＋ إنشاء مفتاح</button></form></section><section class="api-card"><span class="eyebrow">ACTIVE KEYS</span><h2>المفاتيح الحالية</h2><?php if(!$keys):?><p>لا توجد مفاتيح.</p><?php endif?><?php foreach($keys as $k):?><article class="key-card"><div class="key-top"><div><b><?=h($k['key_name'])?></b> <span class="badge <?=$k['is_active']?'on':'off'?>"><?=$k['is_active']?'فعال':'معطل'?></span></div><div><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$k['id']?>"><button class="btn soft" type="submit"><?=$k['is_active']?'تعطيل':'تفعيل'?></button></form> <form method="post" class="deleteForm" style="display:inline"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$k['id']?>"><button class="btn danger" type="submit">حذف</button></form></div></div><div class="key-row"><code class="keybox" data-key="<?=h($k['api_key'])?>">••••••••••••••••••••••••••••••••</code><button type="button" class="btn soft reveal">إظهار</button><button type="button" class="btn soft copy">نسخ</button></div><div class="meta"><span>الإنشاء: <?=h($k['created_at'])?></span><span>آخر استخدام: <?=h($k['last_used_at']?:'لم يستخدم بعد')?></span><span>الاستخدامات: <?=number_format((int)$k['use_count'])?></span></div></article><?php endforeach?></section><footer class="footer" style="padding-inline:0"><div class="footer-brand"><div class="footer-mark">NB</div><div><strong>NotifyBridge</strong><small>API Control Center · V5.0</small></div></div><div class="footer-copy"><b>جميع حقوق التطوير والتصميم : محمد القرعان</b></div><div class="social-icons"><a class="social-icon" href="https://www.facebook.com/elqdes" target="_blank" rel="noopener" aria-label="Facebook @elqdes"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M13.6 22v-9h3l.45-3.5H13.6V7.25c0-1.01.28-1.7 1.73-1.7h1.87V2.42c-.32-.04-1.43-.14-2.72-.14-2.69 0-4.53 1.64-4.53 4.66V9.5H6.9V13h3.05v9z"/></svg></a><a class="social-icon" href="https://www.instagram.com/elqdes/" target="_blank" rel="noopener" aria-label="Instagram @elqdes"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill-rule="evenodd" d="M7 2h10a5 5 0 0 1 5 5v10a5 5 0 0 1-5 5H7a5 5 0 0 1-5-5V7a5 5 0 0 1 5-5zm0 2a3 3 0 0 0-3 3v10a3 3 0 0 0 3 3h10a3 3 0 0 0 3-3V7a3 3 0 0 0-3-3H7zm5 3a5 5 0 1 1 0 10 5 5 0 0 1 0-10zm0 2a3 3 0 1 0 0 6 3 3 0 0 0 0-6zm5.6-3.5a1.2 1.2 0 1 1 0 2.4 1.2 1.2 0 0 1 0-2.4z"/></svg></a></div></footer></main><div id="toast" class="toast"></div><script>(()=>{const toast=document.getElementById('toast');function say(t){toast.textContent=t;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1800)}async function cp(t){try{await navigator.clipboard.writeText(t);say('تم النسخ ✓')}catch(e){window.prompt('انسخ النص:',t)}}document.getElementById('copyEndpoint').addEventListener('click',()=>cp(document.getElementById('endpoint').textContent.trim()));document.querySelectorAll('.reveal').forEach(b=>b.addEventListener('click',()=>{const c=b.parentElement.querySelector('.keybox'),show=b.dataset.show!=='1';c.textContent=show?c.dataset.key:'••••••••••••••••••••••••••••••••';b.textContent=show?'إخفاء':'إظهار';b.dataset.show=show?'1':'0'}));document.querySelectorAll('.copy').forEach(b=>b.addEventListener('click',()=>cp(b.parentElement.querySelector('.keybox').dataset.key)));document.querySelectorAll('.deleteForm').forEach(f=>f.addEventListener('submit',e=>{if(!confirm('حذف هذا المفتاح نهائيًا؟'))e.preventDefault()}));})();</script></body></html>